//! Id tables between an older version and the canonical one, generated by `cargo xtask version-tables`.
//! Shared with `mcr-data-gen`, so this file depends on nothing but `std`.

const MAGIC: &[u8; 4] = b"MCRV";
const FORMAT: u32 = 1;
pub const ABSENT: u16 = u16::MAX;

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct IdMap {
    /// Indexed by the old id.
    pub forward: Vec<u16>,
    /// Indexed by the canonical id.
    pub back: Vec<u16>,
}

impl IdMap {
    #[inline]
    pub fn forward(&self, id: i32) -> Option<i32> {
        Self::get(&self.forward, id)
    }

    #[inline]
    pub fn back(&self, id: i32) -> Option<i32> {
        Self::get(&self.back, id)
    }

    #[inline]
    fn get(table: &[u16], id: i32) -> Option<i32> {
        match table.get(usize::try_from(id).ok()?) {
            Some(&v) if v != ABSENT => Some(i32::from(v)),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct VersionTables {
    pub old_name: String,
    pub old_protocol: u32,
    pub new_name: String,
    pub new_protocol: u32,
    /// Sorted by name. Registries absent here have identical ids in both versions.
    pub maps: Vec<(String, IdMap)>,
    /// Old packet names indexed by old id, for each packet set that has a map; sorted by key.
    pub names: Vec<(String, Vec<String>)>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TableError;

impl std::fmt::Display for TableError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("malformed version tables")
    }
}

impl std::error::Error for TableError {}

impl VersionTables {
    pub fn map(&self, name: &str) -> Option<&IdMap> {
        self.maps
            .binary_search_by(|(n, _)| n.as_str().cmp(name))
            .ok()
            .map(|i| &self.maps[i].1)
    }

    pub fn old_names(&self, key: &str) -> &[String] {
        self.names
            .binary_search_by(|(n, _)| n.as_str().cmp(key))
            .map_or(&[], |i| &self.names[i].1)
    }

    pub fn packet_key(state: &str, direction: &str) -> String {
        format!("packets/{state}/{direction}")
    }

    pub fn registry_key(registry: &str) -> String {
        format!("registry/{registry}")
    }

    pub fn encode(&self) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(MAGIC);
        out.extend_from_slice(&FORMAT.to_le_bytes());
        put_str(&mut out, &self.old_name);
        out.extend_from_slice(&self.old_protocol.to_le_bytes());
        put_str(&mut out, &self.new_name);
        out.extend_from_slice(&self.new_protocol.to_le_bytes());
        out.extend_from_slice(&(self.maps.len() as u32).to_le_bytes());
        for (name, map) in &self.maps {
            put_str(&mut out, name);
            for table in [&map.forward, &map.back] {
                out.extend_from_slice(&(table.len() as u32).to_le_bytes());
                for v in table {
                    out.extend_from_slice(&v.to_le_bytes());
                }
            }
        }
        out.extend_from_slice(&(self.names.len() as u32).to_le_bytes());
        for (key, names) in &self.names {
            put_str(&mut out, key);
            out.extend_from_slice(&(names.len() as u32).to_le_bytes());
            for name in names {
                put_str(&mut out, name);
            }
        }
        out
    }

    pub fn decode(mut bytes: &[u8]) -> Result<Self, TableError> {
        let input = &mut bytes;
        if take(input, 4)? != MAGIC || u32_le(input)? != FORMAT {
            return Err(TableError);
        }
        let old_name = get_str(input)?;
        let old_protocol = u32_le(input)?;
        let new_name = get_str(input)?;
        let new_protocol = u32_le(input)?;
        let count = u32_le(input)? as usize;
        let mut maps = Vec::with_capacity(count.min(1024));
        for _ in 0..count {
            let name = get_str(input)?;
            let forward = get_u16s(input)?;
            let back = get_u16s(input)?;
            maps.push((name, IdMap { forward, back }));
        }
        let count = u32_le(input)? as usize;
        let mut names = Vec::with_capacity(count.min(64));
        for _ in 0..count {
            let key = get_str(input)?;
            let len = u32_le(input)? as usize;
            let mut list = Vec::with_capacity(len.min(1024));
            for _ in 0..len {
                list.push(get_str(input)?);
            }
            names.push((key, list));
        }
        if !input.is_empty()
            || !maps.is_sorted_by(|a, b| a.0 < b.0)
            || !names.is_sorted_by(|a, b| a.0 < b.0)
        {
            return Err(TableError);
        }
        Ok(Self {
            old_name,
            old_protocol,
            new_name,
            new_protocol,
            maps,
            names,
        })
    }
}

fn put_str(out: &mut Vec<u8>, s: &str) {
    out.extend_from_slice(&(s.len() as u16).to_le_bytes());
    out.extend_from_slice(s.as_bytes());
}

fn take<'a>(input: &mut &'a [u8], n: usize) -> Result<&'a [u8], TableError> {
    if input.len() < n {
        return Err(TableError);
    }
    let (head, tail) = input.split_at(n);
    *input = tail;
    Ok(head)
}

fn u32_le(input: &mut &[u8]) -> Result<u32, TableError> {
    Ok(u32::from_le_bytes(
        take(input, 4)?.try_into().map_err(|_| TableError)?,
    ))
}

fn get_str(input: &mut &[u8]) -> Result<String, TableError> {
    let len = u16::from_le_bytes(take(input, 2)?.try_into().map_err(|_| TableError)?);
    String::from_utf8(take(input, len.into())?.to_vec()).map_err(|_| TableError)
}

fn get_u16s(input: &mut &[u8]) -> Result<Vec<u16>, TableError> {
    let len = u32_le(input)? as usize;
    let bytes = take(input, len.checked_mul(2).ok_or(TableError)?)?;
    Ok(bytes
        .as_chunks::<2>()
        .0
        .iter()
        .map(|&c| u16::from_le_bytes(c))
        .collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trip_and_lookup() {
        let tables = VersionTables {
            old_name: "1".into(),
            old_protocol: 1,
            new_name: "2".into(),
            new_protocol: 2,
            maps: vec![(
                "registry/minecraft:item".into(),
                IdMap {
                    forward: vec![0, 2],
                    back: vec![0, ABSENT, 1],
                },
            )],
            names: vec![(
                "packets/play/clientbound".into(),
                vec!["minecraft:a".into()],
            )],
        };
        let bytes = tables.encode();
        let back = VersionTables::decode(&bytes).unwrap();
        assert_eq!(back, tables);
        let map = back.map("registry/minecraft:item").unwrap();
        assert_eq!(map.forward(1), Some(2));
        assert_eq!(map.back(1), None);
        assert_eq!(map.back(-1), None);
        assert_eq!(map.forward(9), None);
        assert!(back.map("registry/minecraft:block").is_none());
        assert_eq!(back.old_names("packets/play/clientbound"), ["minecraft:a"]);
        assert!(back.old_names("packets/play/serverbound").is_empty());
        for cut in 0..bytes.len() {
            assert!(VersionTables::decode(&bytes[..cut]).is_err());
        }
    }
}
